/**
 * `nish/crypto/p384` — ECDSA signature verification over NIST P-384
 * (secp384r1).
 *
 *     import { p384VerifySha384 } from "nish/crypto/p384";
 *
 *     const ok: boolean = p384VerifySha384(pub, message, sig);
 *
 * A public key is the uncompressed SEC 1 encoding of §2.3.3, `0x04 || X || Y`
 * with X and Y 48 big-endian bytes each; a signature is `r` and `s` as 48
 * big-endian bytes each (IEEE P1363). DER, which X.509 and TLS wrap a
 * signature in, is not this module's business. A key or signature of the
 * wrong length, a compressed key, a key that is not on the curve, and an `r`
 * or `s` of 0 or n or more all answer `false`, never a panic.
 *
 * Ported from fiat-crypto (https://github.com/mit-plv/fiat-crypto), fiat-c/src/p384_32.c and fiat-c/src/p384_scalar_32.c. Copyright (c) 2015-2020 the fiat-crypto authors (see the AUTHORS file). Used under the MIT licence; see std/crypto/LICENSE-fiat-crypto.
 *
 * **What is ported and what is not.** The `p384Fiat*` functions are
 * fiat-crypto's generated, formally verified Montgomery arithmetic on twelve
 * `u32` limbs with `u64` products, read at commit
 * abe078c5149bc15bc368c27cc364fdef56470136 — `mul`, `square`, `add`, `sub`
 * and `set_one` mod p, and `mul` and `set_one` mod n — statement for
 * statement, with fiat's variable names. Two things change in the translation
 * and nothing else does. C's out-pointers become a `u64` answer: each of
 * fiat's `addcarryx`, `subborrowx` and `mulx` helpers here answers its two
 * outputs packed, the first in the low 32 bits and the second above them, and
 * the caller splits them, declaring only the halves fiat goes on to read. And
 * each function opens with a length guard, so that the literal indices after
 * it compile with no bounds check. The scalar functions use the field's four
 * helpers, which fiat generates identically for both. Everything else in this
 * file — the curve, the encoding, the inversions, the double-scalar multiply
 * and ECDSA — is written for this module from the documents it names.
 *
 * **The curve** is `y^2 = x^3 - 3x + b` over GF(p), p = 2^384 - 2^128 - 2^96
 * + 2^32 - 1, with the base point G and its order n from SEC 2 §2.5.1 (FIPS
 * 186-4 §D.1.2.4). Points are projective (X : Y : Z), Z = 0 the identity, and
 * are added and doubled with the complete formulas of J. Renes, C. Costello and
 * L. Batina, "Complete addition formulas for prime order elliptic curves"
 * (EUROCRYPT 2016), Algorithms 4 and 6 for a = -3, as `nish/crypto/p256`
 * uses them: P + P, P + (-P) and P + O come out of the same straight line of
 * field operations.
 *
 * **Verify-only and variable time.** Nothing here holds a secret: a public
 * key, a digest and a signature are all public, so there is no private key to
 * keep in a `Secret` and nothing to wipe. `u1 G + u2 Q` is Shamir's trick, one
 * pass over the bits of both scalars from the top with an addition of G, Q or
 * G + Q where a bit is set, and both inversions are Fermat's square-and-
 * multiply; all of them branch on the public scalars and exponents. That is
 * the reason this module has no signing and no key agreement: those would
 * multiply a secret, which these loops must never see (docs/security/
 * crypto-ecc.md, "P-384 is verify-only and variable-time").
 *
 * Private names carry the `p384` prefix because a `std/` module's private
 * functions share the importing program's flat symbol namespace
 * (`docs/wp26-stdlib.md` §3e).
 */
import { sha384 } from "nish/crypto/sha512"
import { timingSafeEqual } from "nish/crypto/ct"

/** The length in bytes of a public key: 0x04, then X and Y big-endian (SEC 1 §2.3.3). */
export const P384_POINT_SIZE: i32 = 97

/** The length in bytes of one scalar, `r` or `s`, big-endian. */
export const P384_SCALAR_SIZE: i32 = 48

/** The length in bytes of a signature: `r` then `s`, 48 big-endian bytes each. */
export const P384_SIGNATURE_SIZE: i32 = 96

/**
 * fiat's `addcarryx_u32`: `arg1 + arg2 + arg3` with `arg1` a carry of 0 or 1.
 * The sum is below 2^33, so its low 32 bits are fiat's `out1` and bit 32 its
 * `out2`.
 */
const p384FiatAddcarryxU32 = (arg1: u32, arg2: u32, arg3: u32): u64 => toU64(arg1) + toU64(arg2) + toU64(arg3)

/**
 * fiat's `subborrowx_u32`: `arg2 - arg1 - arg3` with `arg1` a borrow of 0 or 1.
 * The difference wraps modulo 2^64, so a negative one has every bit from 32 up
 * set; bit 32 alone is kept, which puts fiat's `out2` (1 on a borrow) where
 * `p384FiatAddcarryxU32` puts its carry.
 */
const p384FiatSubborrowxU32 = (arg1: u32, arg2: u32, arg3: u32): u64 =>
  (toU64(arg2) - toU64(arg1) - toU64(arg3)) & 0x1ffffffff

/** fiat's `mulx_u32`: the full 64-bit product, `out1` the low half and `out2` the high. */
const p384FiatMulxU32 = (arg1: u32, arg2: u32): u64 => toU64(arg1) * toU64(arg2)

/**
 * fiat's `cmovznz_u32`: `arg2` when `arg1` is zero and `arg3` otherwise. fiat
 * builds the mask from `!!arg1` behind a value barrier; `ctEq` builds it behind
 * the same kind of barrier, and `ctSelect` blends with it.
 */
const p384FiatCmovznzU32 = (arg1: u32, arg2: u32, arg3: u32): u32 => ctSelect(ctEq(arg1, 0), arg2, arg3)

